-- ======================== HR / QMS 后台菜单与按钮权限种子 ========================
-- 作者：zhicloud
-- 说明：按**代码里实际声明的 @PreAuthorize 权限点**生成（13 个 HR 资源 + 23 个 QMS 资源），不是手抄清单。
--       写法与仓库既有菜单行逐条比对后沿用同一口径：
--         目录 type=1、parent_id=0、path=/hr|/qms；
--         菜单 type=2、path=<资源短名>、component=<模块>/<资源短名>/index、permission=<模块>:<资源>:query；
--         按钮 type=3、parent_id=所属菜单、permission=<模块>:<资源>:<动作>。
--       列集合按 information_schema 核对过：system_menu 没有 tenant_id（菜单是全局表，租户可见性由角色决定）。
--       幂等：目录按 (path,type=1,parent_id=0) 预检，菜单/按钮按 (permission,type) 预检，
--             且只认 deleted = b'0' 的行 —— 已软删的权限点会重新建行，不会静默丢失。
--       刻意不写 system_role_menu：超级管理员走角色旁路即可见，给普通角色授权是运营动作，不在种子里伪造。
-- ======================================================================
INSERT INTO `system_menu` (`id`,`name`,`permission`,`type`,`sort`,`parent_id`,`path`,`icon`,`component`,`component_name`,`status`,`visible`,`keep_alive`,`always_show`,`creator`,`create_time`,`updater`,`update_time`,`deleted`)
