) t
WHERE NOT EXISTS (
    SELECT 1 FROM `system_menu` e
     WHERE e.`deleted` = b'0'
       AND ( (e.`type` = 1 AND e.`parent_id` = 0 AND e.`path` = t.`path` AND t.`type` = 1)
          OR (e.`type` = t.`type` AND e.`permission` = t.`permission` AND t.`permission` <> '') )
);

-- 顺带修一处既有孤儿权限点：id=6740 的「CAPA 阶段流转」按钮 parent_id=0，
-- 不挂在任何菜单下 —— 权限点永远点不到，属"建了但没接线"。挂到本次生成的 CAPA 菜单下。
UPDATE `system_menu` b
  JOIN `system_menu` m ON m.`component` = 'qms/capa/index' AND m.`deleted` = b'0'
   SET b.`parent_id` = m.`id`, b.`sort` = 99
 WHERE b.`id` = 6740 AND b.`parent_id` = 0;
